                        filters.Add(item.Key, item.DocCount ?? 0);
                    }

                    return Ok(new { filters });
                }
                else
                {
                    return Ok(new { status = false, error = result.ServerError });
                }
            }
            else
            {
                return Ok(new { status = false, error = "invalid index" });
            }


        }
        catch (Exception ex)
        {
            return Ok(new { status = false, error = ex.Message });
        }
    }
    return response;
}

